using System;using Exoduser.UnityPort.Core;class Program{static int n;static void C(bool b,string s){n++;if(!b)throw new Exception(s);}static void Main(){var choice=new NextStageDifficultyPolicy();choice.Show(50);C(choice.SelectedIndex==3,"이전 선택 유지");choice.Pick(-1);C(choice.SelectedIndex==4,"왼쪽 wrap");choice.Pick(5);C(choice.SelectedIndex==0,"오른쪽 wrap");choice.Pick(4);C(choice.Confirm()&&!choice.Confirm()&&choice.ConfirmedOffset==100,"확정 한번");choice.Show(33);C(choice.SelectedIndex==2,"알수없는 이전값 기본");choice.Cancel();C(!choice.Active&&!choice.Confirm(),"취소는 확정하지 않음");foreach(int off in new[]{-100,-50,0,50,100}){var s=new Simulation(new SimulationConfig{StageDiffOffset=off,EnemyAiEnabled=false});s.Player.Level=200;s.Random01=()=>.5;var e=s.SpawnEnemy(1000,1000,0);C(e!=null&&e.Level==Math.Max(1,200+off),"실제 적 레벨 offset "+off);var save=new CombatSaveModel{StageDiffOffset=off};var raw=CombatSaveCodec.Encode(save);C(CombatSaveCodec.TryDecode(raw,out var loaded,out var err),"현재 저장 decode "+err);C(loaded.StageDiffOffset==off,"저장 왕복 "+off);}var legacy=CombatSaveCodec.Encode(new CombatSaveModel());legacy.Get("game").Members.RemoveAll(kv=>kv.Key=="stageDiffOff");C(CombatSaveCodec.TryDecode(legacy,out var old,out var why)&&old.StageDiffOffset==0,"기존 저장은 offset0");legacy.Get("game").Set("stageDiffOff",JsonValue.Of(75d));C(!CombatSaveCodec.TryDecode(legacy,out old,out why),"허용되지 않은 offset 저장 거절");Console.WriteLine("PASS "+n);}}